SELECT CAST(AVG(app_count) AS numeric) as avg_apps, 
       CAST(1.5 * AVG(app_count) AS numeric) as threshold
FROM (SELECT COUNT(*) as app_count FROM case_worksite GROUP BY wsstate) sub;

SELECT COUNT(*) FROM (
  SELECT wsstate, wscity, COUNT(*) as cnt 
  FROM case_worksite 
  GROUP BY wsstate, wscity 
  HAVING COUNT(*) > 1.5 * (SELECT CAST(COUNT(*) AS numeric) / COUNT(DISTINCT wsstate) FROM case_worksite)
) sub;

SELECT wsstate FROM (
  SELECT wsstate, COUNT(*) as cnt 
  FROM case_worksite 
  GROUP BY wsstate
) sub
WHERE cnt > 1.5 * (SELECT CAST(COUNT(*) AS numeric) / COUNT(DISTINCT wsstate) FROM case_worksite);

SELECT SUM(cnt) as total_apps_in_concentrated_areas FROM (
  SELECT wsstate, COUNT(*) as cnt 
  FROM case_worksite 
  GROUP BY wsstate
  HAVING COUNT(*) > 1.5 * (SELECT CAST(COUNT(*) AS numeric) / COUNT(DISTINCT wsstate) FROM case_worksite)
) sub;

SELECT COUNT(*) as num_concentrated_areas FROM (
  SELECT wsstate, COUNT(*) as cnt 
  FROM case_worksite 
  GROUP BY wsstate
  HAVING COUNT(*) > 1.5 * (SELECT CAST(COUNT(*) AS numeric) / COUNT(DISTINCT wsstate) FROM case_worksite)
) sub;

WITH state_counts AS (
  SELECT COUNT(*) as cnt FROM case_worksite GROUP BY wsstate
)
SELECT PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY cnt) as median_cnt, 
       PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY cnt) * 1.5 as threshold_15x_median
FROM state_counts;

SELECT wsstate FROM (
  SELECT cw.wsstate, COUNT(DISTINCT c.homefirm) as num_employers
  FROM case_worksite cw
  JOIN cases c ON c.filekey = cw.dockkey
  GROUP BY cw.wsstate
) sub
WHERE num_employers > 1.5 * (SELECT AVG(num_emp) FROM (
  SELECT COUNT(DISTINCT homefirm) as num_emp FROM cases GROUP BY filekey
) t2);

SELECT wsstate FROM (
  SELECT cw.wsstate, COUNT(DISTINCT c.homefirm) as num_employers
  FROM case_worksite cw
  JOIN cases c ON c.filekey = cw.dockkey
  GROUP BY cw.wsstate
) sub
WHERE num_employers > 1.5 * (SELECT AVG(num_emp) FROM (
  SELECT COUNT(DISTINCT homefirm) as num_emp FROM cases GROUP BY filekey
) t2);
